const PAGE_PRESENCE_ACTIVITY_MAX = 80;
const PAGE_PRESENCE_PATH_MAX = 200;
const PAGE_PRESENCE_ANCHOR_MAX = 512;
const PAGE_PRESENCE_NAME_MAX = 80;
const PAGE_PRESENCE_AVATAR_MAX = 2048;
/** One user row plus agent rows; a connection cannot fill the org's table with slots. */
